PROGRAM A8Div2
VAR
  iTio : INT := 10;
  iNoll : INT := 0;
END_VAR
IF TRIG THEN
  O_DIV := 111;
  O_DIV := iTio / iNoll;
  O_EFTER := 222;
END_IF;
END_PROGRAM

PROGRAM A8RDiv
VAR
  rEtt : REAL := 1.0;
  rNoll : REAL := 0.0;
END_VAR
IF TRIG THEN
  O_RDIV := rEtt / rNoll;
END_IF;
END_PROGRAM
